/** Per-connection public PKI or publisher-rooted trust. Hostname verification and global SSL defaults remain intact. */
public final class PinnedTls159 {
 private static final Map<String,String> pins=new ConcurrentHashMap<>();private PinnedTls159(){}
 public static synchronized void hint(String endpoint,String signer)throws IOException{String base=RemoteOffer69.base(endpoint);if(!RemoteOffer69.hash(signer))throw new IOException("HTTPS159_PIN");String old=pins.get(base);if(old!=null&&!old.equals(signer))throw new IOException("HTTPS159_PIN_CHANGED");if(old==null&&pins.size()>=256)throw new IOException("HTTPS159_PIN_LIMIT");pins.put(base,signer);}
 public static void save(Path root,String endpoint,String signer)throws IOException{
  hint(endpoint,signer);String base=RemoteOffer69.base(endpoint);Path dir=FirstLaunchFiles.safe(root.resolve("tls159"));Files.createDirectories(dir);FirstLaunchFiles.privateMode(dir);Path file=dir.resolve(FirstLaunchFiles.sha(base.getBytes(StandardCharsets.UTF_8))+".pin");byte[] b=(base+"\n"+signer+"\n").getBytes(StandardCharsets.UTF_8);
  if(Files.exists(file)){if(!Arrays.equals(FirstLaunchFiles.read(file,8192),b))throw new IOException("HTTPS159_PIN_CHANGED");}else FirstLaunchFiles.write(file,b,false);
 }
 public static void load(Path root)throws IOException{Path dir=FirstLaunchFiles.safe(root.resolve("tls159"));if(!Files.exists(dir))return;try(var paths=Files.list(dir)){var files=paths.limit(257).toList();if(files.size()>256)throw new IOException("HTTPS159_PIN_LIMIT");for(Path p:files){String[] v=new String(FirstLaunchFiles.read(p,8192),StandardCharsets.UTF_8).split("\n",-1);if(v.length!=3||!v[2].isEmpty()||!p.getFileName().toString().equals(FirstLaunchFiles.sha(v[0].getBytes(StandardCharsets.UTF_8))+".pin"))throw new IOException("HTTPS159_PIN");hint(v[0],v[1]);}}}
 private static X509TrustManager defaults()throws GeneralSecurityException{var f=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());f.init((KeyStore)null);for(var m:f.getTrustManagers())if(m instanceof X509TrustManager t)return t;throw new GeneralSecurityException("No default trust manager");}
 public static void verify(X509Certificate[] chain,String signer)throws CertificateException{
  try{if(chain==null||chain.length<2||chain.length>8)throw new CertificateException("HTTPS159_CHAIN");var root=chain[chain.length-1];root.checkValidity();if(root.getBasicConstraints()<0||!FirstLaunchFiles.sha(root.getPublicKey().getEncoded()).equals(signer))throw new CertificateException("HTTPS159_PIN");root.verify(root.getPublicKey());var eku=chain[0].getExtendedKeyUsage();if(chain[0].getBasicConstraints()>=0||eku!=null&&!eku.contains("1.3.6.1.5.5.7.3.1")&&!eku.contains("2.5.29.37.0"))throw new CertificateException("HTTPS159_USAGE");var params=new PKIXParameters(Set.of(new TrustAnchor(root,null)));params.setRevocationEnabled(false);var path=CertificateFactory.getInstance("X.509").generateCertPath(Arrays.asList(chain).subList(0,chain.length-1));CertPathValidator.getInstance("PKIX").validate(path,params);
  }catch(CertificateException e){throw e;}catch(Exception e){throw new CertificateException("HTTPS159_CHAIN",e);}
 }
 public static void apply(HttpsURLConnection connection)throws IOException{
  URI uri;try{uri=connection.getURL().toURI();}catch(URISyntaxException e){throw new IOException(e);}String selected=null;int length=-1;for(var e:pins.entrySet()){URI base=URI.create(e.getKey());int a=base.getPort()<0?443:base.getPort(),b=uri.getPort()<0?443:uri.getPort();if("https".equals(uri.getScheme())&&base.getHost().equalsIgnoreCase(uri.getHost())&&a==b&&uri.getRawPath().startsWith(base.getRawPath())&&base.getRawPath().length()>length){selected=e.getValue();length=base.getRawPath().length();}}
  if(selected==null)return;final String expected=selected;
  try{var system=defaults();var trust=new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return system.getAcceptedIssuers();}public void checkClientTrusted(X509Certificate[] c,String a)throws CertificateException{throw new CertificateException("Unsupported client trust");}public void checkServerTrusted(X509Certificate[] c,String a)throws CertificateException{try{system.checkServerTrusted(c,a);}catch(CertificateException e){verify(c,expected);}}};var ctx=SSLContext.getInstance("TLS");ctx.init(null,new TrustManager[]{trust},new SecureRandom());connection.setSSLSocketFactory(ctx.getSocketFactory());}catch(GeneralSecurityException e){throw new IOException("HTTPS159_CONTEXT",e);}
 }
}
